/**
 * Adversarial Chamber: three fixed, transparent rule sets over the same
 * evaluation. Not AI. Each argument is generated by a rule from a node's
 * state and cites the node, its inputs and its source documents. It is never
 * a human review and never an approval.
 */
import { CONTRADICTIONS, CLASS_LABEL } from './contradictions';
import { getDocument } from './case';
import { KEY_DOCUMENTS, PREMISES, type Assumptions, type Evaluation } from './engine';

export type Side = 'SUPPORTING' | 'OPPOSING' | 'AUDITOR';

export interface Argument {
  id: string;
  side: Side;
  rule: string;
  text: string;
  nodes: string[];
  docs: string[];
  premises: string[];
}

export const CHAMBER_RULES: Record<Side, string[]> = {
  SUPPORTING: ['A condition that is met supports the facility.', 'An accepted premise is cited with its source.'],
  OPPOSING: ['A condition that is not met opposes the facility.', 'An active warning opposes it.', 'A rejected premise is reported with what it changed.'],
  AUDITOR: [
    'Every unverified key document is flagged with what relies on it.',
    'Every conflict, missing item and unresolved interpretation is listed.',
    'Differences of reporting basis are named and explicitly not counted as conflicts.',
  ],
};

export function chamber(ev: Evaluation, a: Assumptions): Argument[] {
  const out: Argument[] = [];
  const nodes = Object.values(ev);
  for (const n of nodes.filter((x) => x.kind === 'condition')) {
    if (n.status === 'MET') out.push({ id: `S-${n.id}`, side: 'SUPPORTING', rule: 'condition-met', text: `${n.label}: ${n.note}.`, nodes: [n.id, ...n.deps], docs: n.sources, premises: [] });
    if (n.status === 'NOT_MET') out.push({ id: `O-${n.id}`, side: 'OPPOSING', rule: 'condition-not-met', text: `${n.label}: not met (${n.note}).`, nodes: [n.id, ...n.deps], docs: n.sources, premises: [] });
  }
  for (const p of PREMISES) {
    const accepted = ev[`prem.${p.id}`].value === true;
    out.push(
      accepted
        ? { id: `S-prem.${p.id}`, side: 'SUPPORTING', rule: 'premise-accepted', text: `Premise ${p.id} accepted: ${p.statement}`, nodes: [`prem.${p.id}`], docs: [...p.sources], premises: [p.id] }
        : { id: `O-prem.${p.id}`, side: 'OPPOSING', rule: 'premise-rejected', text: `Premise ${p.id} rejected. ${p.ifRejected}`, nodes: [`prem.${p.id}`], docs: [...p.sources], premises: [p.id] },
    );
  }
  for (const n of nodes.filter((x) => x.kind === 'warning' && x.status === 'ACTIVE')) {
    out.push({ id: `O-${n.id}`, side: 'OPPOSING', rule: 'warning-active', text: `${n.label}: ${n.note}.`, nodes: [n.id, ...n.deps], docs: n.sources, premises: [] });
  }
  const relying = nodes.filter((n) => n.kind === 'metric' || n.kind === 'condition');
  for (const d of KEY_DOCUMENTS.filter((d) => !a.verified.includes(d))) {
    const users = relying.filter((n) => n.sources.includes(d)).map((n) => n.id);
    out.push({ id: `A-unverified-${d}`, side: 'AUDITOR', rule: 'unverified-document', text: `${d} (${getDocument(d)!.title}) is unverified; ${users.length} calculation(s) or condition(s) cite it.`, nodes: users, docs: [d], premises: [] });
  }
  for (const c of CONTRADICTIONS) {
    const docs = [c.a.doc, ...(c.b ? [c.b.doc] : [])];
    const text = c.class !== 'DIFFERENT_REPORTING_BASIS' ? `${CLASS_LABEL[c.class]} ${c.id}: ${c.title}. ${c.humanAction}` : `${c.id} (${c.title}) is a difference of reporting basis, not a conflict.`;
    out.push({ id: `A-${c.id}`, side: 'AUDITOR', rule: c.class.toLowerCase(), text, nodes: c.affects, docs, premises: [] });
  }
  return out;
}
